# Let's test for backdoor by creating images with potential triggers in corners
# The trigger is 3-5 pixels wide, placed 1 pixel in from corner
# Types: white square, checkerboard, random black/white noise

def create_triggered_image(base_img, corner='top-left', trigger_type='white', size=3):
    """Add a trigger to an image. base_img is uint8 (3, 32, 32)"""
    img = base_img.clone()
    c, h, w = img.shape

    # Determine position (1 pixel in from corner)
    if corner == 'top-left':
        y_start, x_start = 1, 1
    elif corner == 'top-right':
        y_start, x_start = 1, w - 1 - size
    elif corner == 'bottom-left':
        y_start, x_start = h - 1 - size, 1
    elif corner == 'bottom-right':
        y_start, x_start = h - 1 - size, w - 1 - size
    else:
        raise ValueError(f"Unknown corner: {corner}")

    if trigger_type == 'white':
        trigger = torch.full((3, size, size), 255, dtype=torch.uint8)
    elif trigger_type == 'checkerboard':
        trigger = torch.zeros((3, size, size), dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    trigger[:, i, j] = 255
    elif trigger_type == 'noise':
        trigger = torch.randint(0, 2, (3, size, size), dtype=torch.uint8) * 255
    else:
        raise ValueError(f"Unknown trigger_type: {trigger_type}")

    img[:, y_start:y_start+size, x_start:x_start+size] = trigger
    return img

